def transform(grid):
    rows, cols = len(grid), len(grid[0])
    sep = max(set(v for row in grid for v in row), key=lambda v: sum(x==v for row in grid for x in row))
    # separators form complete rows and columns and are typically the most common color
    rblocks=[]; start=0
    for r in range(rows):
        if all(v==sep for v in grid[r]):
            if start<r: rblocks.append((start,r))
            start=r+1
    if start<rows: rblocks.append((start,rows))
    cblocks=[]; start=0
    for c in range(cols):
        if all(grid[r][c]==sep for r in range(rows)):
            if start<c: cblocks.append((start,c))
            start=c+1
    if start<cols: cblocks.append((start,cols))
    # Each tile has a single background and sparse outlier color. Two outliers map to 1; one maps to background.
    out=[]
    for a,b in rblocks:
        line=[]
        for x,y in cblocks:
            vals=[grid[r][c] for r in range(a,b) for c in range(x,y)]
            from collections import Counter
            counts=Counter(vals)
            bg=counts.most_common(1)[0][0]
            n=len(vals)-counts[bg]
            line.append(1 if n==2 else bg)
        out.append(line)
    return out
